package org.sleepwell.app;

import android.content.*;
import android.os.*;
import java.io.*;
import java.util.*;
import java.util.concurrent.*;
import java.util.function.BooleanSupplier;

/** Process-retained explicit save; persisted receipts survive it, but uploads never resume automatically. */
final class CloudAudioJob {
    enum Phase {LOADING,READY,SAVING,CANCELLING,DONE,ERROR,CLEANUP}
    static final class State {
        final Phase phase;final LibraryAudioArchive.Plan plan;final CloudBackupSettings.Destination destination;final List<CloudAudioVersions.Entry> history;final String message;
        State(Phase phase,LibraryAudioArchive.Plan plan,CloudBackupSettings.Destination destination,List<CloudAudioVersions.Entry> history,String message){this.phase=phase;this.plan=plan;this.destination=destination;this.history=List.copyOf(history);this.message=message;}
        boolean busy(){return phase==Phase.LOADING||phase==Phase.SAVING||phase==Phase.CANCELLING;}boolean writing(){return phase==Phase.SAVING||phase==Phase.CANCELLING;}
    }
    private static final Map<Records.Factory,CloudAudioJob> jobs=new IdentityHashMap<>();
    static synchronized CloudAudioJob get(Context app,Records.Factory records){CloudAudioJob existing=jobs.get(records);if(existing!=null)return existing;CloudAudioJob created=new CloudAudioJob(app.getApplicationContext(),records,CloudAudioVersions.factory,CloudBackupSettings.factory);jobs.put(records,created);return created;}
    final Context app;final Records.Factory records;final CloudAudioVersions.Factory preferences;final CloudBackupSettings.Factory destinations;private final ExecutorService worker=Executors.newSingleThreadExecutor(r->new Thread(r,"cloud-audio-backup"));private final Handler main=new Handler(Looper.getMainLooper());
    private volatile State state=new State(Phase.LOADING,null,null,List.of(),"Reading private audio-version receipts…");private volatile boolean cancelled;private volatile CloudBackupProvider provider;private boolean cleanupConfirmed=true;private volatile long generation;
    private CloudAudioJob(Context app,Records.Factory records,CloudAudioVersions.Factory prefs,CloudBackupSettings.Factory destinations){this.app=app;this.records=records;preferences=prefs;this.destinations=destinations;load();}
    State state(){return state;}
    private boolean scope(){return records==Records.PRODUCTION||preferences!=CloudAudioVersions.PRODUCTION&&destinations!=CloudBackupSettings.PRODUCTION;}
    private void publish(Phase phase,LibraryAudioArchive.Plan plan,CloudBackupSettings.Destination destination,List<CloudAudioVersions.Entry> history,String message){main.post(()->state=new State(phase,plan,destination,history,message));}
    void refresh(){if(state.busy()||state.phase==Phase.CLEANUP)return;state=new State(Phase.LOADING,null,state.destination,state.history,"Refreshing actual library counts…");load();}
    private void load(){long own=++generation;worker.execute(()->{LibraryAudioArchive.Plan plan=null;CloudBackupSettings.Destination destination=null;List<CloudAudioVersions.Entry> history=List.of();String error="";try{if(!scope())throw new IOException("Audio history must use the same private data scope as its destination.");history=CloudAudioVersions.inspect(preferences.open(app));destination=CloudBackupSettings.destination(destinations.preferences(app));try(Store store=records.open(app)){plan=LibraryAudioArchive.prepare(app,store,()->own==generation);}if(plan.audio.isEmpty())error="No saved audio recordings. Analysis-only events do not contain audio files.";if(destination.tree.isEmpty())error="Choose a remembered read/write folder in Cloud backup first.";else if(!CloudBackupProvider.granted(app.getContentResolver(),android.net.Uri.parse(destination.tree)))error="Folder access is unavailable. Re-select the destination in Cloud backup.";}catch(Exception failure){error=notice(failure);}if(own!=generation)return;publish(plan==null?Phase.ERROR:Phase.READY,plan,destination,history,error);});}
    void save(){State reviewed=state;if(reviewed.busy()||reviewed.phase==Phase.CLEANUP||reviewed.plan==null||reviewed.plan.audio.isEmpty()||reviewed.destination==null||reviewed.destination.tree.isEmpty())return;cancelled=false;long own=++generation;state=new State(Phase.SAVING,reviewed.plan,reviewed.destination,reviewed.history,"Staging the complete reviewed library privately…");worker.execute(()->{try{saveOwned(reviewed,own);}catch(Exception failure){publish(Phase.ERROR,reviewed.plan,reviewed.destination,reviewed.history,notice(failure));}});}
    private void saveOwned(State reviewed,long own){Object lease=new Object();boolean acquired=false,creationAttempted=false;cleanupConfirmed=true;CloudAudioVersions.Entry entry=null;File staged=null;String error="",warning="";List<CloudAudioVersions.Entry> history=reviewed.history;SharedPreferences prefs=preferences.open(app),destinationPrefs=destinations.preferences(app);BooleanSupplier active=()->!cancelled&&generation==own&&CloudBackupSettings.current(destinationPrefs,reviewed.destination);
        try{if(!scope())throw new IOException("Private destination scope changed.");if(!CloudBackupProvider.granted(app.getContentResolver(),android.net.Uri.parse(reviewed.destination.tree)))throw new IOException("Folder access expired. Choose the destination again before saving audio.");NightAudioArchive.active(active);if(!CloudBackupLease.acquire(lease))throw new IOException("Another folder backup is still finishing. Wait, then review and save again.");acquired=true;entry=new CloudAudioVersions.Entry(UUID.randomUUID().toString(),reviewed.destination,reviewed.plan);CloudAudioVersions.record(prefs,entry);
            try(Store store=records.open(app);LibraryAudioArchive.Snapshot immutable=LibraryAudioArchive.stage(app,store,reviewed.plan,active)){staged=CloudAudioDocuments.fresh(app,"cloud-audio-save-");try(OutputStream output=bounded(new FileOutputStream(staged),LibraryAudioImport.MAX_ZIP)){immutable.write(output,active);}}long size=staged.length();if(size<=0||size>LibraryAudioImport.MAX_ZIP)throw new IOException("The complete ZIP exceeds the supported size. Nothing was omitted.");String expected;try(InputStream input=new FileInputStream(staged)){expected=CloudAudioDocuments.copy(input,null,LibraryAudioImport.MAX_ZIP,active);}NightAudioArchive.active(active);
            CloudBackupProvider selected=new CloudBackupProvider(app,reviewed.destination.tree);provider=selected;entry=entry.next("CREATING","Creating one new ZIP version. A partial file may remain if interrupted.","",size,expected);CloudAudioVersions.record(prefs,entry);NightAudioArchive.active(active);creationAttempted=true;CloudBackupCopy.Document document=selected.create(entry.name,"application/zip");entry=entry.next("WRITING","Writing the complete private snapshot…",document.uri,size,expected);CloudAudioVersions.record(prefs,entry);NightAudioArchive.active(active);
            OutputStream output=null;try{output=selected.output(document);try(InputStream input=new FileInputStream(staged)){String sent=CloudAudioDocuments.copy(input,output,size,active);if(!sent.equals(expected))throw new IOException("The private ZIP changed before upload finished.");}output.flush();}finally{closeProvider(output);}NightAudioArchive.active(active);entry=entry.next("VERIFYING","Reading provider bytes back and checking SHA-256…",document.uri,size,expected);CloudAudioVersions.record(prefs,entry);
            InputStream input=null;String actual;long[] read={0};try{input=selected.input(document);InputStream counted=new FilterInputStream(input){public int read(byte[] bytes,int off,int length)throws IOException{int n=in.read(bytes,off,length);if(n>0)read[0]+=n;return n;}public int read()throws IOException{int n=in.read();if(n>=0)read[0]++;return n;}};actual=CloudAudioDocuments.copy(counted,null,size,active);}finally{closeProvider(input);}NightAudioArchive.active(active);if(read[0]!=size||!actual.equals(expected))throw new IOException("Provider read-back differs from the staged ZIP. This version is unverified.");entry=entry.next("VERIFIED","Provider read-back verified. Your storage app controls remote upload.",document.uri,size,expected);CloudAudioVersions.record(prefs,entry);
        }catch(Exception failure){error=notice(failure);if(entry!=null){String status=!cleanupConfirmed?"CLEANUP":creationAttempted?"UNCERTAIN":cancelled?"CANCELLED":"ERROR";String message=!cleanupConfirmed?"Provider stream cleanup could not be confirmed. Further folder backups stay blocked until the process restarts.":creationAttempted?"A complete or partial file may exist. It is not verified; existing versions were kept. "+error:cancelled?"Cancelled before provider creation. Existing versions were kept.":error;entry=entry.next(status,message,entry.uri,entry.zipBytes,entry.sha);try{CloudAudioVersions.record(prefs,entry);}catch(Exception receiptFailure){error+=" The local receipt could not be updated; review the provider folder before any new save.";}}}
        finally{provider=null;if(staged!=null)try{CloudAudioDocuments.remove(staged);}catch(IOException cleanup){warning=" Private ZIP staging still needs cleanup.";}if(acquired&&cleanupConfirmed)CloudBackupLease.release(lease);try{history=CloudAudioVersions.read(prefs);}catch(Exception failure){error+=" Audio-version history could not be read.";}}
        String message=error.isEmpty()?"Audio ZIP saved and full provider read-back verified. No existing provider file was replaced.":entry!=null?entry.message+(!error.equals(entry.message)?" "+error:""):error;publish(!cleanupConfirmed?Phase.CLEANUP:error.isEmpty()?Phase.DONE:Phase.ERROR,reviewed.plan,reviewed.destination,history,message+warning);
    }
    private void closeProvider(Closeable stream)throws IOException{if(stream==null)return;try{stream.close();}catch(IOException|RuntimeException failure){cleanupConfirmed=false;throw new IOException("Provider stream cleanup could not be confirmed.",failure);}}
    private static OutputStream bounded(OutputStream output,long max){return new FilterOutputStream(output){long count;public void write(int b)throws IOException{if(++count>max)throw new IOException("The complete ZIP exceeds its supported size.");out.write(b);}public void write(byte[] b,int off,int n)throws IOException{if(n>max-count)throw new IOException("The complete ZIP exceeds its supported size.");count+=n;out.write(b,off,n);}};}
    void cancel(){if(!state.writing()||state.phase==Phase.CANCELLING)return;cancelled=true;state=new State(Phase.CANCELLING,state.plan,state.destination,state.history,"Cancelling; waiting for provider calls and stream cleanup…");CloudBackupProvider current=provider;if(current!=null)current.cancel();}
    static String notice(Exception failure){String value=failure.getMessage();return value==null||value.isBlank()||value.length()>500?"Audio backup could not finish. Check the selected folder and library before retrying.":value;}
}
